    private fun build(values: Array<String>): Map<String, String> {
        val map = HashMap<String, String>(keyList.size * 2)
        for (i in 0 until minOf(keyList.size, values.size)) {
            val v = values[i]
            if (v.isNotEmpty()) {
                map[keyList[i]] = v
            }
        }
        return map
    }

